export const CreateObjectView = observer(({model}: {model: CreateObjectModel}) => {
  return (
    <div id="create-object-container"> 
      {/* Asset Selection & Creation */}
      <div id="asset-selector">
        {model.availableAssets.map((asset, index) => (
          <button key={index} id={`asset-${index}`} onClick={() => {
            if (asset) { // Ensure asset exists before triggering creation
              model.createObject(asset).then(() => {
                model.setSelectedAsset(asset); 
              });
            }
          }}>
            {asset} 
          </button>
        ))}
      </div>

      {/* Cleanup Button */}
      <button id="cleanup-scene-btn" onClick={model.cleanupScene}>Cleanup scene</button>
    </div>
  )
})
```

