""")

def recommend_car_size(customer_height):
  """Recommends a car size based on customer height and provided data."""
  for size, details in car_size_data["carSizes"].items():
    height_range = details["heightRange"].split(" - ")
    min_height, max_height = map(lambda x: int(x[:-1].replace("'","")) * 12, height_range)  # Convert to inches for comparison
    if min_height <= int(customer_height.replace("'","")) * 12 <= max_height:
      return details["name"]  
  return "Van"  # Default to Van if no exact match found (assumes exceeding highest range)

