function swapAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectives = words.filter(word => adjectiveDetector(word)); // Utilize a helper function adjectiveDetector (explained below)
  if (adjectives.length >= 2) {
    // Swap the first two adjectives
    [words[adjectives[0]], words[adjectives[1]]] = [words[adjectives[1]], words[adjectives[0]]];
  }
  return words.join(' ');
}

// Helper function to identify adjectives (simplistic for demo, refine for accuracy)
function adjectiveDetector(word) {
  //  Basic regex pattern - expand with more robust NLP techniques in real scenarios
  return /^[a-zA-Z]+(?:-[a-zA-Z]+)*(-ing)?$/.test(word) && !/[0-9]/.test(word); 
}

// Example usage:
const originalSentence = "Beautiful green trees are in the park";
const reorderedSentence = swapAdjectives(originalSentence);
console.log(reorderedSentence); // Output: Green beautiful trees are in the park
```

