import { Injectable } from '@nestjs/common';
import { CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { TypeOrmModule } from '@nestjs/typeorm';
import { UserEntity } from './user.entity';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';

const PERMISSIONS = [
  'READ_USERS',
  'CREATE_USERS',
  'UPDATE_USERS',
  'DELETE_USERS',
  'READ_PRODUCTS',
  'CREATE_PRODUCTS',
  'UPDATE_PRODUCTS',
  'DELETE_PRODUCTS',
  // Add more permissions...
];

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(
    private reflector: Reflector,
    @InjectRepository(UserEntity) private userRepository: Repository<UserEntity>,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiredRoles = this.reflector.get<string[]>('roles', context.getHandler());
    if (!requiredRoles) return true; // Public route

    const request = context.switchToHttp().getRequest();
    const user = request.user as UserEntity;
    if (!user) throw new UnauthorizedException();

    const hasRequiredRole = user.roles.some((role) => requiredRoles.includes(role));
    return hasRequiredRole;
  }
}

export const auth = (roles: string[]) => ({
  target: 'method',
  useValue: RolesGuard,
  options: { roles },
});
```

**Explanation (for clarity, NOT part of the merged `index.js`):**

1. **`PERMISSIONS` Array:** Defines a centralized list of permission names for your application's authorization logic. Extend it as needed.

2. **`RolesGuard`:**
   - Injects `Reflector` to fetch `@Roles` decorators from controllers/methods.
   - Uses `TypeORM` (`userRepository`) to retrieve user data (specifically roles) during authorization checks.
   - `canActivate` determines access:
     - If `@Roles` decorator isn't present (empty `requiredRoles`), allows all (public route).
     - Otherwise, verifies if the logged-in user

