function getValueByDotNotation(options, keyString) {
  // Split the dot-notated key into individual keys
  const keys = keyString.split('.');
  let currentEntry = options; 

  // Traverse the nested structure using recursion
  for (const key of keys) {
    if (typeof currentEntry === 'object' && currentEntry !== null && key in currentEntry) {
      currentEntry = currentEntry[key];
    } else {
      // Key not found at any level, return undefined
      return undefined; 
    }
  }
  return currentEntry; 
}
